css:
.aura-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #2a0845 0%, #6441a5 45%, #ff4e8b 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #ffffff;
}

.aura-sim-header {
    background: rgba(255,255,255,0.08);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 22px;
    padding: 32px 36px;
    margin-bottom: 22px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.15);
}
.aura-sim-brand {
    font-size: 0.72rem;
    letter-spacing: 0.35em;
    color: #ffd1e6;
    font-weight: 600;
    margin-bottom: 10px;
}
.aura-sim-header h1 {
    font-size: 2rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    background: linear-gradient(120deg, #ffffff, #ffd1e6, #b48bff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}
.aura-sim-subtitle {
    color: rgba(255,255,255,0.78);
    font-size: 0.95rem;
    font-weight: 500;
}

.aura-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.14);
    border-radius: 14px;
    padding: 14px 22px;
    margin-bottom: 22px;
    font-size: 0.95rem;
}
.aura-sim-period-label span {
    margin-right: 6px;
}
.aura-sim-period-label span + span {
    font-weight: 700;
    color: #ffd1e6;
}
.aura-sim-stage-name {
    color: #ffffff;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.85rem;
}

.aura-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.aura-sim-kpi-card {
    background: rgba(255,255,255,0.09);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 18px;
    padding: 20px 18px;
    transition: transform 0.25s ease, background 0.25s ease;
    position: relative;
    overflow: hidden;
}
.aura-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #ff4e8b, #b48bff);
}
.aura-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.14);
}
.aura-sim-kpi-label {
    color: rgba(255,255,255,0.72);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 10px;
    font-weight: 600;
}
.aura-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #ffffff;
}
.aura-kpi-revenue .aura-sim-kpi-value {
    background: linear-gradient(120deg, #7cffb2, #9be8ff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.aura-kpi-awareness .aura-sim-kpi-value {
    background: linear-gradient(120deg, #ffd1e6, #b48bff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.aura-sim-briefing {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.15);
    border-left: 4px solid #ff4e8b;
    border-radius: 16px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.aura-sim-briefing-tag {
    font-size: 0.7rem;
    letter-spacing: 0.25em;
    color: #ffd1e6;
    font-weight: 700;
    margin-bottom: 8px;
}
.aura-sim-briefing-title {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 10px;
    color: #ffffff;
}
.aura-sim-briefing-body {
    color: rgba(255,255,255,0.85);
    line-height: 1.55;
    font-size: 0.95rem;
}

.aura-sim-controls {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 20px;
    padding: 26px 28px;
    margin-bottom: 24px;
}
.aura-sim-controls h3 {
    font-size: 1.15rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 16px;
}
.aura-sim-section-title {
    font-size: 0.78rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #ffd1e6;
    font-weight: 700;
    margin: 16px 0 10px 0;
}

.aura-sim-slider-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px 20px;
}
.aura-sim-slider-cell label {
    display: flex;
    justify-content: space-between;
    font-size: 0.88rem;
    font-weight: 500;
    color: rgba(255,255,255,0.9);
    margin-bottom: 6px;
}
.aura-sim-pct {
    color: #ffd1e6;
    font-weight: 700;
}
.aura-sim-controls input[type="range"] {
    width: 100%;
    accent-color: #ff4e8b;
}

.aura-sim-total-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    background: rgba(0,0,0,0.25);
    border-radius: 10px;
    margin: 14px 0 4px 0;
    font-weight: 600;
    font-size: 0.95rem;
}
.aura-sim-total-good { color: #7cffb2; font-weight: 700; }
.aura-sim-total-bad { color: #ff8aa0; font-weight: 700; }

.aura-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
}
.aura-sim-input-grid label {
    font-size: 0.88rem;
    font-weight: 500;
    color: rgba(255,255,255,0.9);
    margin-bottom: 6px;
    display: flex;
    justify-content: space-between;
}
.aura-sim-controls select,
.aura-sim-controls input[type="number"],
.aura-sim-controls input[type="text"] {
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.22);
    color: #ffffff;
    border-radius: 10px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
}
.aura-sim-controls select option {
    background: #2a0845;
    color: #ffffff;
}
.aura-sim-hint {
    font-size: 0.76rem;
    color: rgba(255,255,255,0.65);
    margin-top: 6px;
}

.aura-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    flex-wrap: wrap;
}
.aura-sim-actions .btn-primary {
    background: linear-gradient(135deg, #ff4e8b, #b48bff);
    border: none;
    padding: 12px 28px;
    font-weight: 700;
    letter-spacing: 0.04em;
    border-radius: 12px;
    box-shadow: 0 8px 22px rgba(255,78,139,0.35);
    transition: transform 0.2s ease;
}
.aura-sim-actions .btn-primary:hover {
    transform: translateY(-2px);
    background: linear-gradient(135deg, #ff6aa0, #c79fff);
}
.aura-sim-actions .btn-outline-secondary {
    border: 1px solid rgba(255,255,255,0.3);
    color: #ffffff;
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    padding: 10px 20px;
}
.aura-sim-actions .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.12);
    color: #ffffff;
}

.aura-sim-history-wrap {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.14);
    border-radius: 18px;
    padding: 22px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.aura-sim-history-wrap h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 14px;
}
.aura-sim-history-wrap table {
    color: rgba(255,255,255,0.92);
    width: 100%;
}
.aura-sim-history-wrap table thead th {
    color: #ffd1e6;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(255,255,255,0.2);
    padding: 10px 8px;
}
.aura-sim-history-wrap table tbody td {
    border-top: 1px solid rgba(255,255,255,0.08);
    padding: 10px 8px;
    font-size: 0.9rem;
}

.aura-sim-charts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 20px;
    margin-bottom: 40px;
}
.aura-sim-chart-card {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255,255,255,0.14);
    border-radius: 18px;
    padding: 20px 22px;
}
.aura-sim-chart-card h4 {
    color: #ffd1e6;
    font-size: 0.8rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 14px;
}
.aura-sim-chart-box {
    position: relative;
    height: 280px;
}

@media (max-width: 768px) {
    .aura-sim-container { padding: 16px; }
    .aura-sim-header { padding: 22px 20px; }
    .aura-sim-header h1 { font-size: 1.4rem; }
    .aura-sim-kpi-value { font-size: 1.3rem; }
    .aura-sim-chart-box { height: 220px; }
}

/* EQIL 2026-11-12: accessibility and debrief (append-only, namespaced) */
.aura-sim-container :focus-visible { outline: 3px solid #ffd1e6; outline-offset: 2px; }
.aura-sim-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (prefers-reduced-motion: reduce) { .aura-sim-container *, .aura-cm * { transition: none !important; animation: none !important; } }
.aura-cm { text-align: left; color: #1f1430; }
.aura-cm-score { text-align: center; }
.aura-cm-num { font-size: 2.6rem; font-weight: 800; color: #b0145a; }
.aura-cm-of { font-size: 1.1rem; color: #4a3a5c; margin-left: 2px; }
.aura-cm-tier { text-align: center; font-weight: 700; font-size: 1.15rem; margin: 4px 0 12px; color: #1f1430; }
.aura-cm-kpis { list-style: none; padding: 0; margin: 0 0 12px; display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 8px; }
.aura-cm-kpis li { background: #f6eef9; border-radius: 8px; padding: 8px 10px; display: flex; flex-direction: column; }
.aura-cm-kpis span { font-size: 0.8rem; color: #4a3a5c; }
.aura-cm-kpis strong { font-size: 1.05rem; color: #1f1430; }
.aura-cm-h { font-size: 1rem; font-weight: 700; margin: 12px 0 6px; color: #1f1430; }
.aura-cm-list { margin: 0 0 8px 1.1rem; padding: 0; }
.aura-cm-list li { margin-bottom: 6px; line-height: 1.4; }

