            this.TIER_EFFICIENCY = {
                nano:  { reach: 0.35, engage: 1.70, convert: 1.45, awareness: 0.25 },
                micro: { reach: 0.70, engage: 1.30, convert: 1.20, awareness: 0.55 },
                macro: { reach: 1.30, engage: 0.80, convert: 0.85, awareness: 1.05 },
                mega:  { reach: 1.80, engage: 0.45, convert: 0.55, awareness: 1.45 }
            };

            this.PLATFORM_MOD = {
                tiktok:    { reach: 1.25, engage: 1.30, convert: 0.90, awareness: 1.10 },
                instagram: { reach: 1.00, engage: 1.00, convert: 1.20, awareness: 0.95 },
                youtube:   { reach: 0.80, engage: 1.10, convert: 1.10, awareness: 0.95 },
                mixed:     { reach: 1.05, engage: 1.05, convert: 1.05, awareness: 1.05 }
            };

            this.STAGE_BUDGET = 500000;
            this.AOV = 22;
            this.CONVERSION_CALIBRATION = 550;
            this.MARGIN = 0.60;
            this.BASE_DEMAND = 1.0;
            this.ENGAGEMENT_SCALE = 3;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    remainingBudget: this.STAGE_BUDGET * 5,
                    brandAwareness: 35.0,
                    followers: 350000,
                    engagementRate: 2.5,
                    totalRevenue: 0,
                    totalProfit: 0,
                    complianceScore: 100,
                    reputation: 50,
                    revenueHistory: [],
                    awarenessHistory: [],
                    engagementHistory: [],
                    followersHistory: [],
                    complianceHistory: [],
                    crisisTriggered: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    nanoPct: 20,
                    microPct: 20,
                    macroPct: 20,
                    megaPct: 20,
                    organicPct: 20,
                    platform: 'tiktok',
                    authenticity: 5,
                    compliance: 5
                };
            }
            this._bindControls();
            this._updateBriefing(state);
            this._refreshSliderLabels();
        }

        _bindControls() {
            var ids = ['nanoPct','microPct','macroPct','megaPct','organicPct','authenticitySlider','complianceSlider'];
            var outs = {
                nanoPct: 'nanoPctOut',
                microPct: 'microPctOut',
                macroPct: 'macroPctOut',
                megaPct: 'megaPctOut',
                organicPct: 'organicPctOut',
                authenticitySlider: 'authenticityOut',
                complianceSlider: 'complianceOut'
            };
            var self = this;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el.dataset.bound) {
                    el.addEventListener('input', function() {
                        var outEl = document.getElementById(outs[id]);
                        if (outEl) {
                            if (id === 'authenticitySlider' || id === 'complianceSlider') {
                                outEl.textContent = el.value;
                            } else {
                                outEl.textContent = el.value + '%';
                            }
                        }
                        self._updateTotal();
                    });
                    el.dataset.bound = '1';
                }
            });
            this._updateTotal();
        }

        _refreshSliderLabels() {
            var map = {
                nanoPct: 'nanoPctOut',
                microPct: 'microPctOut',
                macroPct: 'macroPctOut',
                megaPct: 'megaPctOut',
                organicPct: 'organicPctOut'
            };
            Object.keys(map).forEach(function(id) {
                var el = document.getElementById(id);
                var out = document.getElementById(map[id]);
                if (el && out) out.textContent = el.value + '%';
            });
            var auth = document.getElementById('authenticitySlider');
            var authOut = document.getElementById('authenticityOut');
            if (auth && authOut) authOut.textContent = auth.value;
            var comp = document.getElementById('complianceSlider');
            var compOut = document.getElementById('complianceOut');
            if (comp && compOut) compOut.textContent = comp.value;
        }

        _updateTotal() {
            var total = this._readPct('nanoPct') + this._readPct('microPct') + this._readPct('macroPct') + this._readPct('megaPct') + this._readPct('organicPct');
            var out = document.getElementById('totalAllocationOut');
            if (out) {
                out.textContent = total + '%';
                out.className = (total === 100) ? 'aura-sim-total-good' : 'aura-sim-total-bad';
            }
        }

        _readPct(id) {
            var el = document.getElementById(id);
            return el ? parseInt(el.value, 10) : 0;
        }

        validateDecisions(decisions) {
            decisions.nanoPct = this._readPct('nanoPct');
            decisions.microPct = this._readPct('microPct');
            decisions.macroPct = this._readPct('macroPct');
            decisions.megaPct = this._readPct('megaPct');
            decisions.organicPct = this._readPct('organicPct');

            var platformEl = document.getElementById('platformSelect');
            if (platformEl) decisions.platform = platformEl.value;

            var authEl = document.getElementById('authenticitySlider');
            if (authEl) decisions.authenticity = parseInt(authEl.value, 10);

            var compEl = document.getElementById('complianceSlider');
            if (compEl) decisions.compliance = parseInt(compEl.value, 10);

            var total = decisions.nanoPct + decisions.microPct + decisions.macroPct + decisions.megaPct + decisions.organicPct;
            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning') + ' ' + total + '%', 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod || 1;

            var stageBudget = this.STAGE_BUDGET;
            var paidBudget = stageBudget * (1 - d.organicPct / 100);
            var organicBudget = stageBudget - paidBudget;

            var nanoSpend = stageBudget * d.nanoPct / 100;
            var microSpend = stageBudget * d.microPct / 100;
            var macroSpend = stageBudget * d.macroPct / 100;
            var megaSpend = stageBudget * d.megaPct / 100;

            var inflation = (period >= 2) ? 1.25 : 1.0;
            var microEffective = microSpend / inflation;

            var platform = d.platform || 'tiktok';
            var platMod = this.PLATFORM_MOD[platform] || this.PLATFORM_MOD.mixed;

            var authBoost = 0.60 + (d.authenticity / 10) * 0.90;

            var algoShift = 1.0;
            if (period >= 4) {
                if (platform === 'instagram') algoShift = 0.80;
                if (platform === 'tiktok') algoShift = (d.nanoPct + d.microPct) > 45 ? 1.20 : 1.0;
            }

            var saturation = (period >= 5) ? 0.85 : 1.0;

            var te = this.TIER_EFFICIENCY;
            var rawReach = (
                nanoSpend * te.nano.reach +
                microEffective * te.micro.reach +
                macroSpend * te.macro.reach +
                megaSpend * te.mega.reach
            ) / 1000;

            var reach = Math.round(rawReach * platMod.reach * algoShift * saturation);

            var engagementPoints = (
                nanoSpend * te.nano.engage +
                microEffective * te.micro.engage +
                macroSpend * te.macro.engage +
                megaSpend * te.mega.engage
            ) / 1000;
            var rawEngagement = engagementPoints * platMod.engage * authBoost * algoShift;
            // engagement rate: interactions per person reached, scaled to a rate (1.2: no longer pinned at the cap)
            var engagementPct = Math.min(12, Math.max(0.5, rawEngagement / Math.max(reach, 1) * this.ENGAGEMENT_SCALE));

            var conversionBase = (
                nanoSpend * te.nano.convert +
                microEffective * te.micro.convert +
                macroSpend * te.macro.convert +
                megaSpend * te.mega.convert
            ) / 1000;
            var buyers = Math.round(conversionBase * platMod.convert * authBoost * algoShift * saturation * 0.18 * this.CONVERSION_CALIBRATION);

            var attributedRevenue = Math.round(buyers * this.AOV);

            var incrementalityFactor = 0.70 - (d.authenticity < 4 ? 0.10 : 0) + (period >= 4 ? -0.05 : 0);
            attributedRevenue = Math.round(attributedRevenue * Math.max(0.45, incrementalityFactor));

            var grossProfit = Math.round(attributedRevenue * this.MARGIN);
            var roi = stageBudget > 0 ? ((grossProfit - stageBudget) / stageBudget) * 100 : 0;

            var awarenessLift = (
                nanoSpend * te.nano.awareness +
                microEffective * te.micro.awareness +
                macroSpend * te.macro.awareness +
                megaSpend * te.mega.awareness
            ) / 80000 * platMod.awareness * saturation;
            awarenessLift = Math.round(awarenessLift * 10) / 10;
            awarenessLift = Math.min(awarenessLift, 9.5);

            var followerGrowthPct = 2 + (d.nanoPct + d.microPct) * 0.05 + (d.organicPct * 0.18) + (d.authenticity * 0.3);
            if (period >= 5 && d.organicPct >= 30) followerGrowthPct += 4;
            var newFollowers = Math.round(ds.followers * followerGrowthPct / 100);

            var complianceHit = 0;
            var crisisMsg = '';
            if (d.compliance <= 3) {
                complianceHit = 20 + Math.round(Math.random() * 15);
                crisisMsg = window.mySimulation.t('msg_profeco');
            } else if (d.compliance <= 6) {
                if (Math.random() < 0.25) complianceHit = 8;
            }

            var crisisHit = 0;
            if (period === 3 && d.megaPct >= 30 && d.compliance <= 6 && !ds.crisisTriggered) {
                crisisHit = Math.round(attributedRevenue * 0.25);
                attributedRevenue -= crisisHit;
                grossProfit = Math.round(attributedRevenue * this.MARGIN);
                roi = ((grossProfit - stageBudget) / stageBudget) * 100;
                awarenessLift = Math.max(0, awarenessLift - 1.5);
                ds.crisisTriggered = true;
                crisisMsg = window.mySimulation.t('msg_scandal');
            }

            ds.remainingBudget -= stageBudget;
            ds.brandAwareness = Math.min(95, Math.round((ds.brandAwareness + awarenessLift) * 10) / 10);
            ds.engagementRate = Math.round(engagementPct * 10) / 10;
            ds.followers += newFollowers;
            ds.totalRevenue += attributedRevenue;
            ds.totalProfit += grossProfit;
            ds.complianceScore = Math.max(0, ds.complianceScore - complianceHit);

            ds.revenueHistory.push(attributedRevenue);
            ds.awarenessHistory.push(ds.brandAwareness);
            ds.engagementHistory.push(ds.engagementRate);
            ds.followersHistory.push(ds.followers);
            ds.complianceHistory.push(ds.complianceScore);
            ds.score = this._overallScore(ds.totalProfit, period, ds.brandAwareness, ds.complianceScore, ds.engagementRate, ds.followers);
            ds.performance = { overallScore: ds.score, rating: this._rateCreator(ds.score) };
            ds.performanceTier = this._rateCreator(ds.score);

            if (crisisMsg) {
                window.mySimulation.uiManager.showNotification(crisisMsg, 'warning');
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 300);

            return {
                period: period,
                reach: reach,
                buyers: buyers,
                revenue: attributedRevenue,
                profit: grossProfit,
                roi: Math.round(roi * 10) / 10,
                awareness: ds.brandAwareness,
                engagement: ds.engagementRate,
                followers: ds.followers,
                awarenessLift: awarenessLift,
                newFollowers: newFollowers,
                compliance: ds.complianceScore,
                platform: d.platform,
                crisis: crisisHit > 0
            };
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : null;

            var title = t ? t(round.key + '_title') : round.defaultTitle;
            var text = t ? t(round.key + '_text') : round.defaultText;
            var stage = t ? t(round.stageKey) : round.defaultStage;

            if (!title || title === (round.key + '_title')) title = round.defaultTitle;
            if (!text || text === (round.key + '_text')) text = round.defaultText;
            if (!stage || stage === round.stageKey) stage = round.defaultStage;

            var titleEl = document.getElementById('briefingTitle');
            var bodyEl = document.getElementById('briefingText');
            var stageEl = document.getElementById('stageName');
            if (titleEl) titleEl.textContent = title;
            if (bodyEl) bodyEl.textContent = text;
            if (stageEl) stageEl.textContent = stage;
        }

