        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = this._tr();
            var totalRevenue = history.reduce(function(s, r) { return s + (r.results && r.results.revenue || 0); }, 0);
            var totalProfit = history.reduce(function(s, r) { return s + (r.results && r.results.profit || 0); }, 0);
            var totalSpend = history.length * this.STAGE_BUDGET;
            var roi = totalSpend > 0 ? ((totalProfit - totalSpend) / totalSpend) * 100 : 0;
            var last = history[history.length - 1].results || {};
            var finalAwareness = last.awareness != null ? last.awareness : 35;
            var finalCompliance = last.compliance != null ? last.compliance : 100;
            var overallScore = this._overallScore(totalProfit, history.length, finalAwareness, finalCompliance, last.engagement || 0, last.followers || 350000);
            /* one verdict, from the score: the band and the label can no longer disagree */
            var tier = this._rateCreator(overallScore);

            var dec = history.map(function(r) { return r.decisions || {}; });
            var later = dec.slice(1);
            var microLater = later.length ? later.reduce(function(s, d) { return s + (d.microPct || 0); }, 0) / later.length : 0;
            var scripted = dec.some(function(d) { return d.authenticity != null && d.authenticity <= 6; });
            var minimal = dec.some(function(d) { return d.compliance != null && d.compliance <= 3; });
            var moderate = dec.some(function(d) { return d.compliance >= 4 && d.compliance <= 6; });
            var scandal = history.some(function(r) { return r.results && r.results.crisis; });
            var lastDec = dec[dec.length - 1];
            var paidOnly = dec.every(function(d) { return !d.organicPct; });

            var insights = [];
            if (scandal) insights.push(t('ins_concentration'));
            if (minimal) insights.push(t('ins_profeco_minimal'));
            else if (moderate) insights.push(t('ins_disclosure_gap'));
            if (scripted) insights.push(t('ins_scripted'));
            if (history.length >= 2 && microLater >= 25) insights.push(t('ins_micro_held'));
            if (history.length >= 5 && (lastDec.organicPct || 0) >= 30) insights.push(t('ins_community'));
            else if (history.length >= 5 && paidOnly) insights.push(t('ins_paid_only'));
            insights.push(roi >= 0 ? t('ins_roi_pos') : t('ins_roi_neg'));

            /* turning point: the stage with the lowest ROI */
            var worst = 0;
            history.forEach(function(r, i) { if ((r.results && r.results.roi || 0) < (history[worst].results && history[worst].results.roi || 0)) worst = i; });

            return {
                overallScore: overallScore,
                totalScore: overallScore,
                composite: overallScore,
                score: overallScore,
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                roi: Math.round(roi * 10) / 10,
                finalAwareness: finalAwareness,
                finalCompliance: finalCompliance,
                finalFollowers: last.followers || 350000,
                turningStage: worst + 1,
                turningRoi: history[worst].results ? history[worst].results.roi : 0,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: t('tier_' + tier),
                insights: insights.slice(0, 5),
                totalPeriods: history.length
            };
        }

        _tr() {
            var sim = window.mySimulation;
            return function(k) {
                var v = sim && sim.t ? sim.t(k) : k;
                return (v == null || v === '') ? k : v;
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = this._tr();
            var esc = function(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var num = function(v, d) { return (Math.round((v || 0) * Math.pow(10, d)) / Math.pow(10, d)).toLocaleString(); };
            var html = '<div class="aura-cm" role="status">';
            html += '<div class="aura-cm-score"><span class="aura-cm-num">' + esc(summary.overallScore) + '</span><span class="aura-cm-of">/100</span></div>';
            html += '<div class="aura-cm-tier">' + esc(summary.performanceLabel || '') + '</div>';
            html += '<ul class="aura-cm-kpis">';
            html += '<li><span>' + esc(t('cm_roi')) + '</span><strong>' + num(summary.roi, 1) + '%</strong></li>';
            html += '<li><span>' + esc(t('awareness_label')) + '</span><strong>' + num(summary.finalAwareness, 1) + '%</strong></li>';
            html += '<li><span>' + esc(t('compliance_label')) + '</span><strong>' + num(summary.finalCompliance, 0) + '</strong></li>';
            html += '<li><span>' + esc(t('followers_label')) + '</span><strong>' + num(summary.finalFollowers, 0) + '</strong></li>';
            html += '</ul>';
            if (summary.turningStage) {
                html += '<h4 class="aura-cm-h">' + esc(t('cm_turning')) + '</h4><p>' + esc(t('cm_turning_text').replace('{n}', summary.turningStage).replace('{roi}', num(summary.turningRoi, 1))) + '</p>';
            }
            var ins = summary.insights || [];
            if (ins.length) {
                html += '<h4 class="aura-cm-h">' + esc(t('cm_insights')) + '</h4><ul class="aura-cm-list">';
                ins.forEach(function(x) { html += '<li>' + esc(x) + '</li>'; });
                html += '</ul>';
            }
            html += '<h4 class="aura-cm-h">' + esc(t('cm_questions')) + '</h4><ol class="aura-cm-list">';
            html += '<li>' + esc(t('cm_q1')) + '</li><li>' + esc(t('cm_q2')) + '</li><li>' + esc(t('cm_q3')) + '</li></ol>';
            html += '</div>';
            return html;
        }

        _overallScore(totalProfit, periods, awareness, compliance, engagement, followers) {
            var c = function (x) { return Math.max(0, Math.min(100, x)); };
            var spend = periods * this.STAGE_BUDGET;
            var roi = spend > 0 ? ((totalProfit - spend) / spend) * 100 : 0;
            var sRoi = c((roi + 60) / 100 * 100);
            var sAw = c((awareness - 35) / 35 * 100);
            var sComp = c(compliance);
            var sEng = c(engagement / 8 * 100);
            var sFol = c((followers / 350000 - 1) / 0.5 * 100);
            return Math.round(0.35 * sRoi + 0.25 * sAw + 0.20 * sComp + 0.10 * sEng + 0.10 * sFol);
        }

        _rateCreator(s) {
            /* bands derived from the sweep: expert play 85 to 92, untouched start and random play near 58 */
            return s >= 85 ? 'excellent' : s >= 70 ? 'strong' : s >= 50 ? 'adequate' : 'underperforming';
        }

